create policy kiru_acceptances_guardian_insert on public.kiru_document_acceptances for insert to authenticated with check (accepted_by = (select auth.uid()) and exists (select 1 from public.student_guardians sg where sg.student_id = kiru_document_acceptances.student_id and sg.guardian_id = (select auth.uid())) and exists (select 1 from public.kiru_documents d where d.id = kiru_document_acceptances.document_id and d.requires_acceptance = true and (d.target_student_id = kiru_document_acceptances.student_id or d.target_student_id is null)));
